<template><span v-if="required"><el-button link type="primary" @click="open">审核 / 送审</el-button><el-dialog v-model="visible" title="当前工作稿审核" width="min(780px,calc(100vw - 32px))" append-to-body @closed="close"><el-alert title="只送审服务器已保存的版本；表单中的未保存修改不会送审。保存新稿会使旧审核失效。" :closable="false"/><p>当前工作版本 {{version}}</p><el-button v-if="canEdit" type="primary" :loading="busy" @click="submit">提交已保存工作稿审核</el-button><el-button @click="load">刷新</el-button><el-table :data="rows"><el-table-column prop="reviewId" label="申请" width="80"/><el-table-column prop="contentVersion" label="工作版本" width="90"/><el-table-column label="状态"><template #default="s">{{reviewLabels[s.row.status]}}</template></el-table-column><el-table-column prop="createTime" label="提交时间" width="170"/><el-table-column label="操作"><template #default="s"><el-button link @click="detail.open(s.row.reviewId)">快照与处理</el-button></template></el-table-column></el-table><pagination v-if="total" :total="total" v-model:page="pg.pageNum" v-model:limit="pg.pageSize" @pagination="load"/></el-dialog><ReviewDetail ref="detail" @changed="changed"/></span></template>
<script setup>
import {ref,reactive,computed,onMounted,onBeforeUnmount,onDeactivated} from 'vue';import{ElMessage}from'element-plus';import{workflow,reviewLabels}from'@/api/cms/workflow';import auth from '@/plugins/auth';import ReviewDetail from './ReviewDetail.vue'
const props=defineProps({kind:{type:String,required:true},objectId:{type:Number,required:true},version:{type:Number,required:true},required:Boolean}),emit=defineEmits(['changed']),visible=ref(false),rows=ref([]),total=ref(0),busy=ref(false),detail=ref(),pg=reactive({pageNum:1,pageSize:10});let epoch=0
const canEdit=computed(()=>auth.hasPermi(`cms:${props.kind.toLowerCase()}:edit`));async function open(){visible.value=true;pg.pageNum=1;await load()}async function load(){const n=++epoch,r=await workflow('review/object','get',undefined,{kind:props.kind.toUpperCase(),objectId:props.objectId,...pg});if(n===epoch&&visible.value){rows.value=r.rows;total.value=r.total}}
async function submit(){if(busy.value)return;busy.value=true;try{await workflow('review','post',{kind:props.kind.toUpperCase(),objectId:props.objectId,contentVersion:props.version});ElMessage.success('已送审，等待其他审核人处理');await load()}finally{busy.value=false}}
function changed(){load();emit('changed')}function close(){++epoch;visible.value=false;rows.value=[];detail.value?.close()}onBeforeUnmount(close);onDeactivated(close)
</script>
